const int NUM_TREES = 12;

inline int predict_tree_node(const Node* tree, const float* x) {
    int curr = 0;
    while (tree[curr].feature != -1) {
        if (x[tree[curr].feature] <= tree[curr].threshold) {
            curr = tree[curr].left_child;
        } else {
            curr = tree[curr].right_child;
        }
    }
    return tree[curr].class_pred;
}

inline int predict_sentinel_regime(const float* raw_inputs) {
    float x[5];
    for (int i = 0; i < 5; i++) {
        x[i] = (raw_inputs[i] - SCALER_MEAN[i]) / SCALER_SCALE[i];
    }
    int vote[3] = {0, 0, 0};
    vote[predict_tree_node(TREE_0, x)]++;
    vote[predict_tree_node(TREE_1, x)]++;
    vote[predict_tree_node(TREE_2, x)]++;
    vote[predict_tree_node(TREE_3, x)]++;
    vote[predict_tree_node(TREE_4, x)]++;
    vote[predict_tree_node(TREE_5, x)]++;
    vote[predict_tree_node(TREE_6, x)]++;
    vote[predict_tree_node(TREE_7, x)]++;
    vote[predict_tree_node(TREE_8, x)]++;
    vote[predict_tree_node(TREE_9, x)]++;
    vote[predict_tree_node(TREE_10, x)]++;
    vote[predict_tree_node(TREE_11, x)]++;
    int max_class = 0;
    for (int c = 1; c < 3; c++) {
        if (vote[c] > vote[max_class]) max_class = c;
    }
    return max_class;
}

